      "content": "#include "request.h"
#include <sstream>
#include <stdexcept>
#include <string_view>

namespace ws::http {

Request::Request() noexcept : state_(std::make_unique<NotStarted>(*this)), method_(Method::Get), keep_alive_(false) {}

Request::explicit Request(Buffer& buf) : Request() { Parse(buf); }

Request::~Request() noexcept {}

void Request::Parse(Buffer& buf) {
    std::string line;
    while (std::getline(buf, line)) {
        state_->Parse(line);
    }
}

std::optional<std::string_view> Request::Header(std::string_view key) const noexcept {
    auto it = headers_.find(key);
    if (it != headers_.end()) {
        return it->second;
    }
    return std::nullopt;
}

std::optional<std::string_view> Request::Post(std::string_view key) const noexcept {
    auto it = post_data_.find(key);
    if (it != post_data_.end()) {
        return it->second;
    }
    return std::nullopt;
}

std::size_t Request::PostSize() const noexcept {
    return post_data_.size();
}

http::Method Request::Method() const noexcept {
    return method_;
}

std::string_view Request::Path() const noexcept {
    return path_;
}

std::string_view Request::Version() const noexcept {
    return version_;
}

bool Request::KeepAlive() const noexcept {
    return keep_alive_;
}

Request::State::State(Request& parser) noexcept : parser_(parser) {}

void Request::NotStarted::Parse(const std::string& line) {
    std::istringstream iss(line);
    std::string method_str, path, version;
    if (!(iss >> method_str >> path >> version)) {
        throw std::invalid_argument("Invalid request line");
    }
    parser_.method_ = StringToMethod(method_str);
    parser_.path_ = path;
    parser_.version_ = version;
    parser_.state_ = std::make_unique<Header>(parser_);
}

void Request::Header::Parse(const std::string& line) {
    if (line.empty()) {
        parser_.state_ = std::make_unique<Body>(parser_);
        return;
    }
    auto colon_pos = line.find(':');
    if (colon_pos == std::string::npos) {
        throw std::invalid_argument("Invalid header format");
    }
    std::string key = line.substr(0, colon_pos);
    std::string value = line.substr(colon_pos + 2); // Skip the colon and space
    parser_.headers_[key] = value;
}

void Request::Body::Parse(const std::string& body) {
    if (parser_.method_ == Method::Post) {
        ParsePost(body);
    }
    parser_.state_ = std::make_unique<Finished>(parser_);
}

void Request::Body::ParsePost(const std::string& body) {
    if (parser_.headers_["Content-Type"] == "application/x-www-form-urlencoded") {
        ParseURLEncodedPost(body);
    }
}

void Request::Body::ParseURLEncodedPost(const std::string& body) {
    // Implementation for parsing URL-encoded POST data
}

[[noreturn]] void Request::Finished::Parse(const std::string& content) {
    throw std::logic_error("Parsing finished");
}

