#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string_view>

namespace ws::http {

Response::explicit Response(std::filesystem::path root_dir) noexcept : root_dir_(root_dir), keep_alive_(false) {}

Response::~Response() noexcept { Clear(); }

Response& Response::SetKeepAlive(bool set) noexcept {
    keep_alive_ = set;
    return *this;
}

std::optional<MappedReadOnlyFile> Response::Build(Buffer& buf, std::filesystem::path file, StatusCode& code) noexcept {
    if (!CheckFile()) {
        code = StatusCode::NotFound;
        AddPredefinedErrorContent(buf);
        return std::nullopt;
    }
    mapped_file_ = MapFile();
    code = StatusCode::OK;
    Build(buf);
    return mapped_file_;
}

void Response::Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code) noexcept {
    if (!std::filesystem::exists(html)) {
        code = StatusCode::NotFound;
        AddPredefinedErrorContent(buf);
        return;
    }
    std::ifstream file_stream(html);
    if (!file_stream.is_open()) {
        code = StatusCode::Forbidden;
        AddPredefinedErrorContent(buf);
        return;
    }
    std::string content((std::istreambuf_iterator<char>(file_stream)), std::istreambuf_iterator<char>());
    file_stream.close();
    code = StatusCode::OK;
    Build(buf, &params);
}

void Response::Build(Buffer& buf, StatusCode code, std::string msg) noexcept {
    AddStatusLine(buf);
    AddHeaders(buf);
    AddPredefinedErrorContent(buf, msg);
}

void Response::Clear() noexcept {
    if (mapped_file_.IsValid()) {
        mapped_file_.Unmap();
    }
}

void Response::Build(Buffer& buf, const Parameters* params) noexcept {
    Clear();
    AddStatusLine(buf);
    AddHeaders(buf);
    if (params) {
        AddParamContent(buf, *params);
    } else {
        AddMappedContent(buf);
    }
}

bool Response::CheckFile() {
    return std::filesystem::exists(root_dir_ / mapped_file_.Path()) &&
           std::filesystem::is_regular_file(root_dir_ / mapped_file_.Path());
}

MappedReadOnlyFile Response::MapFile() {
    // Implementation for mapping file into memory
}

void Response::AddStatusLine(Buffer& buf) const noexcept {
    buf.Append(version);
    buf.Append(" ");
    buf.Append(std::to_string(StatusCodeToInteger(code)));
    buf.Append(" ");
    buf.Append(StatusCodeToMessage(code));
    buf.Append(new_line);
}

void Response::AddHeaders(Buffer& buf) const noexcept {
    if (keep_alive_) {
        buf.Append("Connection: keep-alive");
        buf.Append(new_line);
    }
    // Add other headers as necessary
    buf.Append(new_line);
}

void Response::AddMappedContent(Buffer& buf) noexcept {
    if (!mapped_file_.IsValid()) return;
    buf.Append(mapped_file_.Data(), mapped_file_.Size());
}

void Response::AddParamContent(Buffer& buf, const Parameters& params) const noexcept {
    std::string content = mapped_file_.ToString();
    for (const auto& [key, value] : params) {
        content = PutParamIntoHTML(content, {{key, value}});
    }
    buf.Append(content);
}

void Response::AddPredefinedErrorContent(Buffer& buf, std::string_view msg) noexcept {
    // Implementation for adding predefined error content
}

